content.content:
1	/* Werkbank Cycles – shared stylesheet */
2	:root { --ink: #1f2328; --muted: #5a6068; --accent: #b3541e; --paper: #fbfaf7; --line: #ddd8cf; }
3	* { box-sizing: border-box; }
4	body { margin: 0; font-family: "Helvetica Neue", Arial, sans-serif; line-height: 1.55; color: var(--ink); background: var(--paper); }
5	a { color: var(--accent); }
6	.site-header { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 0.75rem; padding: 0.75rem 1rem; border-bottom: 1px solid var(--line); }
7	.brand { display: flex; align-items: center; gap: 0.5rem; font-weight: bold; color: var(--ink); text-decoration: none; }
8	.site-header nav { display: flex; flex-wrap: wrap; gap: 1rem; }
9	.site-header nav a, .nav-link { color: var(--ink); text-decoration: none; cursor: pointer; }
10	.site-header nav a:hover, .nav-link:hover { color: var(--accent); }
11	main { max-width: 46rem; margin: 0 auto; padding: 1rem; }
12	main img { max-width: 100%; height: auto; }
13	.meta { color: var(--muted); font-size: 0.9rem; }
14	.price { font-weight: bold; }
15	.prices { width: 100%; border-collapse: collapse; }
16	.prices th, .prices td { text-align: left; padding: 0.4rem; border-bottom: 1px solid var(--line); vertical-align: top; }
17	.hours { list-style: none; padding: 0; }
18	form label { display: block; margin-top: 0.75rem; }
19	form input, form textarea { width: 100%; padding: 0.4rem; font: inherit; }
20	form button { margin-top: 1rem; padding: 0.5rem 1rem; background: var(--accent); color: #fff; border: 0; font: inherit; }
21	.comments { border-top: 1px solid var(--line); margin-top: 2rem; }
22	.comment { margin: 1rem 0; }
23	.site-footer { max-width: 46rem; margin: 2rem auto 0; padding: 1rem; color: var(--muted); font-size: 0.85rem; border-top: 1px solid var(--line); }
24	.print-page { max-width: 40rem; }
25	@media print { .no-print { display: none; } body { background: #fff; } }
